      const refresh=async()=>{const r=await api('/api/content',{operation:'list'}),list=$('post-jobs');list.replaceChildren();for(const j of r.jobs){const row=node('article',undefined,'record');row.append(node('strong',j.post.channel+' / '+j.status),node('pre',`${j.post.publishAt} (UTC)\nAccount: ${j.post.accountId}\n${j.post.text}\n${j.post.assets.join('\n')}`));if(j.status==='draft')row.append(studioButton('Review & authorize scheduled publishing',()=>guard(async()=>{if(!await approve('Authorize this exact scheduled post?',JSON.stringify(j.post,null,2)))return;await api('/api/content',{operation:'approve',id:j.id,version:j.version,approved:true});audit('content.approve',j.id+'; publication still pending.');await refresh();})));if(['draft','approved'].includes(j.status))row.append(studioButton('Cancel',()=>guard(async()=>{await api('/api/content',{operation:'cancel',id:j.id});await refresh();})));if(j.provider)row.append(node('pre',JSON.stringify(j.provider,null,2)));list.append(row);}};
      $('post-form').onsubmit=e=>{e.preventDefault();guard(async()=>{const r=await api('/api/content',{operation:'create',post:{channel:$('post-channel').value,accountId:$('post-account').value,text:$('post-text').value,assets:$('post-assets').value.split('\n').filter(Boolean),publishAt:new Date($('post-time').value).toISOString()}});result('Draft queued: '+r.job.id+'. Not approved or published.');audit('content.draft',r.job.id);await refresh();});};$('post-refresh').onclick=()=>guard(refresh);guard(refresh);
