      const items=['Give it a home — Render cloud runtime; Free sleeps, paid always-on is needed for dependable scheduling.','Agentic harness — bounded five-step observe/plan/tool loop; no unattended side effects.','Model selection — Claude Sonnet/Opus, OpenAI, OpenRouter, Grok and Gemini adapters.','Teach it who you are — profiling interview and an editable memory/profile.md.','Persistent memory — JSON/Markdown workspace with Redis or a durable disk, not localStorage alone.','Add skills — modular capability registry and reviewed agent/MCP/browser/content references.','Connect tools — Google read-only Workspace, search, media, publishing and browser adapters.','Communication channels — chat, browser STT/TTS; calls are labeled rehearsals, not real telephony.','AI command center — reactor HUD, missions, approval panels, workspace, content queue and ledger.'];content.append(node('p','Reference: https://www.instagram.com/p/De4fEpUhqTi/','muted'));const ol=node('ol');items.forEach(s=>ol.append(node('li',s)));content.append(ol);content.insertAdjacentHTML('beforeend','<h3>Owner profiling interview</h3><p class="muted">Save only details you want Jarvis to remember. This writes an explicit profile to the server workspace and does not publish it in GitHub.</p><form class="tool-form" id="active-tool-form">'+field('profile-name','Preferred name')+field('profile-business','Business / project context')+field('profile-goals','Your main goals')+field('profile-preferences','How should Jarvis work with you?')+'<label>Background / decisions<textarea id="profile-notes" rows="5"></textarea></label><button type="submit" class="primary">REVIEW & SAVE PROFILE</button><button id="profile-interview" type="button">Start AI interview</button></form><div id="tool-result" class="tool-result"></div>');$('profile-interview').onclick=()=>submit('Run onboarding. Ask one question at a time to learn my business, life goals and preferences. Read memory/profile.md before asking.');$('active-tool-form').onsubmit=e=>{e.preventDefault();guard(async()=>{const profile=`# Owner profile\n\nPreferred name: ${$('profile-name').value}\nBusiness/projects: ${$('profile-business').value}\nGoals: ${$('profile-goals').value}\nPreferences: ${$('profile-preferences').value}\n\n## Background and decisions\n${$('profile-notes').value}\n`;const old=await workspaceAPI({operation:'read',path:'memory/profile.md'});if(!await approve('Save this long-term profile?',profile))return;await workspaceAPI({operation:'write',path:'memory/profile.md',content:profile,version:old.version,approved:true});result('Profile saved. The model harness automatically reads memory files on each mission.');audit('profile.write','memory/profile.md updated after review.');});};
