window.speechSynthesis?.addEventListener('voiceschanged',populateVoices);populateVoices();
function switchBrain(id){if(!brains.some(b=>b.id===id))return;data.brain=id;document.body.dataset.brain=id;$('brain-label').textContent=brains.find(b=>b.id===id).name.toUpperCase();persist();audit('brain.switch',`${id}: ${status.brains?.[id]?'live provider configured':'not configured; no fabricated AI fallback'}`);return `${brains.find(b=>b.id===id).name} selected, sir. ${status.brains?.[id]?'My next response will use this provider.':'This brain needs its server API key before I can use it.'}`;}
function approve(title,detail){if(confirmResolve)confirmResolve(false);$('confirm-title').textContent=title;$('confirm-detail').textContent=detail;$('confirm-dialog').showModal();return new Promise(resolve=>{confirmResolve=resolve;});}
function closeConfirm(value){$('confirm-dialog').close();confirmResolve?.(value);confirmResolve=null;}
$('confirm-yes').onclick=()=>closeConfirm(true);$('confirm-no').onclick=()=>closeConfirm(false);$('confirm-dialog').addEventListener('cancel',()=>closeConfirm(false));
async function submit(text){text=text.trim();if(!text)return;if(busy){toast('A mission is already running. Stop it before starting another.');return;}message('user',text);$('command').value='';stopped=false;interrupt();recognition?.abort();busy=true;const ticket=++generation;activeController=new AbortController();renderCounts();setState('processing');const m=mission(text,['Understand request','Select capability','Execute with permissions','Record outcome']);step(m,0,'Request received');try{let answer;const brainMatch=text.match(/(?:switch|change).*(?:brain|model).*?(claude|grok|gemini|opus|openrouter|openai)/i);if(brainMatch){answer=switchBrain(brainMatch[1].toLowerCase());step(m,1,'Brain router');}else if(/^remember\b/i.test(text)){const fact=text.replace(/^remember\s+(?:that\s+)?/i,'');remember('fact',fact,fact);answer='Committed to device memory, sir. You can edit, export or delete it in Memory & Projects.';step(m,1,'Structured memory');}else if(/website.*(?:\$?500|sell)|restaurants?.*website|lead.*(?:discover|business)/i.test(text)){step(m,1,'Business pipeline');await openTool('business');$('business-query').value=text;answer='Business mission ready. Run live discovery, verify a published lead and contact, then generate a website preview and approve the outreach. No invented restaurant or silent email.';}else if(/(?:call|book|reserve).*(?:table|restaurant|appointment|vendor)/i.test(text)){step(m,1,'Call agent simulation');await openTool('calls');$('call-purpose').value=text;answer='Call rehearsal ready, sir. This deployment does not place telephone calls; use the labeled simulation to prepare the booking conversation.';}else if(/(?:invoice|create.*document|generate.*task)/i.test(text)){step(m,1,'Document generator');await openTool('documents');answer='Document studio open. Add the client, line items and terms; I will prepare a preview and downloadable document.';}else if(/screen|look at.*(?:display|monitor)/i.test(text)){await openTool('screen');step(m,1,'Permission-gated visual observation');answer='Observation console ready. Choose a screen, then explicitly send a frame to a configured vision brain.';}else if(/search.*(?:files|folder)|computer|system search/i.test(text)){await openTool('files');step(m,1,'Local file picker');answer='System console ready. Choose files or a folder to search. Browser permissions do not allow unrestricted operating-system control.';}else if(/unread|calendar|schedule|email|inbox/i.test(text)){step(m,1,'Connected Google reads');const r=await api('/api/mission',{message:text,brain:data.brain,memory:context(text)},activeController.signal);answer=r.reply||r.summary||JSON.stringify(r);if(r.sources)showSources(r.sources);}else if(/^(?:search|research|find)\b/i.test(text)){step(m,1,'Live internet search');const r=await api('/api/research',{query:text},activeController.signal);answer=r.answer||r.results.map(x=>x.title+' — '+x.content).join('\n');showSources(r.results);}else{step(m,1,'Brain + memory context');const r=await api('/api/mission',{message:text,brain:data.brain,memory:context(text)},activeController.signal);answer=r.reply||r.summary||JSON.stringify(r);}
if(ticket!==generation)return;step(m,2,'Observed result received');step(m,3,'Saved to mission history');finish(m,answer);audit('mission',answer.slice(0,400));busy=false;setState('idle');reply(answer);}catch(e){if(ticket!==generation)return;const reason=e.name==='AbortError'?'Mission cancelled.':e.message;finish(m,reason,'BLOCKED');audit('mission',reason,'blocked');busy=false;setState('idle');reply(reason);}finally{if(ticket===generation){busy=false;renderCounts();scheduleListen();}}}
function context(query){const words=query.toLowerCase().split(/\W+/).filter(w=>w.length>3);const ranked=data.records.map(r=>({r,score:words.reduce((n,w)=>n+(String(r.title+' '+r.detail).toLowerCase().includes(w)?1:0),0)+(r.type==='preference'?2:0)})).sort((a,b)=>b.score-a.score);return ranked.slice(0,12).map(({r})=>`${r.type}: ${r.title}\n${r.detail}`).join('\n').slice(0,12000);}
function showSources(sources){const a=node('article',undefined,'message');a.append(node('span','SOURCES','speaker'));for(const s of sources||[])if(s.url)a.append(safeLink(s.url,s.title));$('messages').append(a);$('messages').scrollTop=$('messages').scrollHeight;}
function formHTML(content){return `<form class="tool-form" id="active-tool-form">${content}</form><div class="tool-result" id="tool-result" role="status"></div>`;}
function field(id,label,type='text',value='',required=true){return `<label>${label}<input id="${id}" type="${type}" ${required?'required':''} value="${escapeHTML(value)}"></label>`;}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function result(text){const r=$('tool-result');if(r)r.textContent=text;}
async function guard(fn){const stamp=uiGeneration;const button=$('active-tool-form')?.querySelector('button[type=submit]');if(button)button.disabled=true;try{await fn();}catch(e){if(stamp===uiGeneration){result(e.message);toast(e.message);}audit('tool',e.message,'blocked');}finally{if(button?.isConnected)button.disabled=false;}}
async function openTool(id){uiGeneration++;if(callTimer){clearTimeout(callTimer);callTimer=null;}const title={calendar:'Calendar intelligence',email:'Communication studio',calls:'Reservation agent / simulation',documents:'Document studio',brains:'Choose your intelligence',screen:'Visual observation',files:'System & website accounts',business:'Business generation mission',registry:'Capability registry & connections'};$('tool-title').textContent=title[id]||id;$('tool-content').replaceChildren();if(!$('tool-dialog').open)$('tool-dialog').showModal();const content=$('tool-content');
if(id==='brains'){const p=node('p','Skin changes immediately. Responses are routed to the selected real provider only when its server key is configured. API keys never enter the client bundle.','muted');content.append(p);const grid=node('div',undefined,'tool-grid');for(const b of brains){const btn=node('button',undefined,'brain-card'+(data.brain===b.id?' selected':''));btn.append(node('strong',b.name),node('small',b.description),node('small',status.brains?.[b.id]?'LIVE PROVIDER CONFIGURED':'API KEY REQUIRED'));btn.onclick=()=>{reply(switchBrain(b.id));openTool('brains');};grid.append(btn);}content.append(grid);}
if(id==='calendar'){const today=new Date();content.innerHTML=`<p class="muted">${status.googleConnected?'Google connected: read-only calendar access.':'Connect Google for live event summaries; local calendar works without a provider.'}</p><div class="local-actions"><button id="google-connect">Connect Google</button><button id="google-calendar">Read next 7 days</button><button id="ics-export">Export local ICS</button></div><h3 id="month-title"></h3><div id="calendar-grid" class="calendar-grid"></div>`+formHTML(field('event-title','Event title')+field('event-date','Starts (local timezone)','datetime-local')+field('event-duration','Duration (minutes)','number','60')+field('event-place','Location','text','',false)+'<button type="submit" class="primary">SAVE LOCAL EVENT</button>')+'<div id="event-list"></div>';
$('month-title').textContent=today.toLocaleDateString(undefined,{month:'long',year:'numeric'});for(const day of ['S','M','T','W','T','F','S'])$('calendar-grid').append(node('span',day));for(let i=0;i<new Date(today.getFullYear(),today.getMonth(),1).getDay();i++)$('calendar-grid').append(node('span',''));for(let i=1;i<=new Date(today.getFullYear(),today.getMonth()+1,0).getDate();i++){const b=node('button',i,i===today.getDate()?'today':'');b.onclick=()=>{$('event-date').value=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(i).padStart(2,'0')}T12:00`;};$('calendar-grid').append(b);}
const render=()=>{const list=$('event-list');list.replaceChildren();for(const e of [...data.events].sort((a,b)=>a.start.localeCompare(b.start))){const r=node('article',undefined,'record');r.append(node('strong',e.title),node('p',`${new Date(e.start).toLocaleString()} · ${e.duration} min · ${e.place||'No location'}`));const d=node('button','Delete');d.onclick=()=>{data.events=data.events.filter(x=>x.id!==e.id);persist();render();};r.append(d);list.append(r);}};render();$('google-connect').onclick=()=>{if(status.googleConfigured)location.href='/auth/google';else result('Set GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET and GOOGLE_REDIRECT_URI in Render.');};$('google-calendar').onclick=()=>guard(async()=>{const r=await api('/api/mission',{message:'Check my calendar for the next seven days',brain:data.brain});result(r.reply);audit('calendar.read',r.reply);});$('ics-export').onclick=()=>{const esc=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const dt=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Jarvis//Local Calendar//EN',...data.events.flatMap(e=>['BEGIN:VEVENT',`UID:${e.id}@jarvis`,`DTSTAMP:${dt(new Date())}`,`DTSTART:${dt(e.start)}`,`DTEND:${dt(new Date(new Date(e.start).getTime()+e.duration*60000))}`,`SUMMARY:${esc(e.title)}`,`LOCATION:${esc(e.place)}`,'END:VEVENT']),'END:VCALENDAR'];download('jarvis-events.ics',lines.join('\r\n')+'\r\n','text/calendar');};$('active-tool-form').onsubmit=e=>{e.preventDefault();const start=new Date($('event-date').value);const duration=Number($('event-duration').value);if(!Number.isFinite(start.getTime())||duration<=0||duration>10080)return result('Enter a valid start time and duration.');const event={id:crypto.randomUUID(),title:$('event-title').value,start:start.toISOString(),duration,place:$('event-place').value};data.events.push(event);persist();render();result('Saved locally. Export ICS to add it to another calendar.');audit('calendar.local.create',event.title);};}
if(id==='email'){content.innerHTML='<p class="muted">Google inbox access is read-only. Drafts stay on this device. Optional Resend sends only after explicit approval using a verified sender configured by the owner.</p><div class="local-actions"><button id="unread">Check unread email</button></div>'+formHTML(field('email-to','Recipient (published or supplied)','email')+field('email-subject','Subject')+'<label>Message<textarea id="email-body" required rows="7"></textarea></label><div class="local-actions"><button type="submit" class="primary">SAVE DRAFT</button><button type="button" id="email-compose">Open email app</button><button type="button" id="email-send">Approve & send via provider</button></div>')+'<div id="draft-list"></div>';$('unread').onclick=()=>guard(async()=>{const r=await api('/api/mission',{message:'Check unread email',brain:data.brain});result(r.reply);});const values=()=>({to:$('email-to').value,subject:$('email-subject').value,body:$('email-body').value});$('active-tool-form').onsubmit=e=>{e.preventDefault();const d={id:crypto.randomUUID(),...values(),at:new Date().toISOString()};data.drafts.unshift(d);persist();result('Draft saved. Nothing sent.');audit('email.draft',d.subject);};$('email-compose').onclick=()=>{if(!$('active-tool-form').reportValidity())return;const d=values();location.href=`mailto:${encodeURIComponent(d.to)}?subject=${encodeURIComponent(d.subject)}&body=${encodeURIComponent(d.body)}`;};$('email-send').onclick=()=>guard(async()=>{if(!$('active-tool-form').reportValidity())return;const d=values();if(!status.emailConfigured)return result('Sending is not configured. Set RESEND_API_KEY, RESEND_FROM and APP_ACCESS_TOKEN. You can still save a draft or open your email app.');if(!await approve('Send this email?',`To: ${d.to}\nSubject: ${d.subject}\n\n${d.body}`))return;const r=await api('/api/email/send',{...d,approved:true,requestId:crypto.randomUUID()});result('Provider accepted email. Message ID: '+r.id+'. Delivery is not confirmed.');audit('email.send','Provider accepted '+r.id);});for(const d of data.drafts.slice(0,10)){const b=node('button',d.subject+' → '+d.to);b.onclick=()=>{$('email-to').value=d.to;$('email-subject').value=d.subject;$('email-body').value=d.body;};$('draft-list').append(b);}}
if(id==='calls'){content.innerHTML='<p class="muted">SIMULATION ONLY — no phone call is placed and no reservation is booked. This rehearsal builds a human-reviewed request and transcript.</p>'+formHTML(field('call-business','Business or provider')+field('call-phone','Published phone number','tel')+field('call-purpose','Purpose / appointment / party size')+field('call-time','Requested date and time','datetime-local')+'<div class="local-actions"><button type="submit" class="primary">START SIMULATION</button><button id="call-stop" type="button">Stop rehearsal</button></div>')+'<div id="call-lines" class="call-lines" aria-live="polite"></div>';$('call-stop').onclick=()=>{clearTimeout(callTimer);callTimer=null;result('Rehearsal stopped. No call placed.');};$('active-tool-form').onsubmit=e=>{e.preventDefault();clearTimeout(callTimer);const business=$('call-business').value,purpose=$('call-purpose').value,time=$('call-time').value;const lines=[['SYSTEM','Connecting simulated line…'],['JARVIS',`Good evening. I am preparing a request for ${business}.`],['SIMULATED HOST','How may I assist you?'],['JARVIS',`${purpose}. Requested time: ${new Date(time).toLocaleString()}. Is there availability?`],['SYSTEM','Availability cannot be verified in a simulation. Await a real representative.'],['JARVIS','I will not claim a booking without confirmation. Rehearsal complete, sir.']];$('call-lines').replaceChildren();let i=0;const advance=()=>{if(i>=lines.length){callTimer=null;result('Simulation complete. No reservation made.');remember('task',`Contact ${business}`,`${purpose}; requested ${time}; phone ${$('call-phone').value}; not booked.`);audit('call.simulation','No call placed; rehearsal saved.','simulated');return;}const [speaker,text]=lines[i++],p=node('p');p.append(node('b',speaker+': '),node('span',text));$('call-lines').append(p);$('call-lines').scrollTop=$('call-lines').scrollHeight;callTimer=setTimeout(advance,1400);};advance();};}
if(id==='documents'){content.innerHTML='<p class="muted">Generate a clean invoice, task plan or document locally. Preview is sandboxed. Download the HTML and print it to PDF in your browser. No invented taxes, totals or client data.</p>'+formHTML('<label>Document type<select id="doc-type"><option value="invoice">Invoice</option><option value="tasks">Task plan</option><option value="document">Document</option></select></label>'+field('doc-title','Title','text','Invoice')+field('doc-from','Your business / author')+field('doc-client','Client / recipient')+field('doc-currency','Currency code','text','USD')+'<label>Items: description | quantity | unit price (or one task / paragraph per line)<textarea id="doc-items" required rows="5" placeholder="Website design | 1 | 500"></textarea></label><label>Terms / notes<textarea id="doc-notes" placeholder="Payment terms, due date, agreed details…"></textarea></label><button type="submit" class="primary">GENERATE PREVIEW</button>')+'<div id="doc-preview"></div>';$('active-tool-form').onsubmit=e=>{e.preventDefault();const kind=$('doc-type').value,title=$('doc-title').value,author=$('doc-from').value,client=$('doc-client').value,currency=$('doc-currency').value.toUpperCase();let rows='',total=0;const items=$('doc-items').value.trim().split('\n');if(kind==='invoice'){let fmt;try{fmt=new Intl.NumberFormat(undefined,{style:'currency',currency});}catch{return result('Enter an ISO currency code such as USD.');}for(const line of items){const [description,q,p]=line.split('|').map(s=>s.trim()),qty=Number(q),price=Number(p);if(!description||!q||!p||!Number.isFinite(qty)||!Number.isFinite(price)||qty<=0||price<0)return result('Each invoice line needs description | positive quantity | non-negative unit price.');const amount=Math.round(qty*price*100)/100;total+=amount;rows+=`<tr><td>${escapeHTML(description)}</td><td>${qty}</td><td>${fmt.format(price)}</td><td>${fmt.format(amount)}</td></tr>`;}rows=`<table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${rows}</tbody></table><h2>Total: ${fmt.format(total)}</h2><p>No taxes or additional fees added.</p>`;}else rows=`<${kind==='tasks'?'ol':'div'}>${items.map(s=>`<${kind==='tasks'?'li':'p'}>${escapeHTML(s)}</${kind==='tasks'?'li':'p'}>`).join('')}</${kind==='tasks'?'ol':'div'}>`;const html=documentHTML(title,`<p class="label">${escapeHTML(kind.toUpperCase())} / ${new Date().toLocaleDateString()}</p><h1>${escapeHTML(title)}</h1><p>From: ${escapeHTML(author)}<br>For: ${escapeHTML(client)}</p>${rows}<p>${escapeHTML($('doc-notes').value).replace(/\n/g,'<br>')}</p>`);preview($('doc-preview'),html,'jarvis-document.html');result('Document created locally. Check the details before sending.');remember(kind==='tasks'?'task':'project',title,`${author} → ${client}\n${$('doc-items').value}\n${$('doc-notes').value}`);audit('document.create',title);};}
if(id==='screen'){content.innerHTML='<p class="muted">Share only a window you consent to reveal. Capture sends one frame to the selected brain; it is not continuous recording. Avoid passwords and private information. Stop sharing at any time.</p><div class="local-actions"><button id="screen-start">Choose screen</button><button id="screen-stop">Stop sharing</button></div><video id="screen-video" autoplay muted playsinline></video>'+formHTML(field('screen-question','Question about the visible screen','text','Describe what you can see and suggest the next action.')+'<button type="submit" class="primary">CAPTURE & ANALYZE ONE FRAME</button>');screenVideo=$('screen-video');if(screenStream)screenVideo.srcObject=screenStream;$('screen-start').onclick=()=>guard(async()=>{if(!navigator.mediaDevices?.getDisplayMedia)throw Error('Screen capture is not supported in this browser.');if(screenStream)screenStream.getTracks().forEach(t=>t.stop());screenStream=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:5},audio:false});screenVideo.srcObject=screenStream;$('observation-state').textContent='SHARING';screenStream.getVideoTracks()[0].addEventListener('ended',stopScreen);audit('screen.share','User-selected screen; frames sent only on request.');});$('screen-stop').onclick=stopScreen;$('active-tool-form').onsubmit=e=>{e.preventDefault();guard(async()=>{if(!screenStream||!screenVideo.videoWidth)throw Error('Choose a screen and wait for the preview first.');if(!status.brains?.[data.brain])throw Error('Configure the selected vision brain first.');if(!await approve('Send this screen frame?',`One frame will be sent to ${data.brain} for: ${$('screen-question').value}`))return;const canvas=document.createElement('canvas'),ratio=Math.min(1,1280/screenVideo.videoWidth);canvas.width=screenVideo.videoWidth*ratio;canvas.height=screenVideo.videoHeight*ratio;canvas.getContext('2d').drawImage(screenVideo,0,0,canvas.width,canvas.height);const r=await api('/api/vision',{brain:data.brain,message:$('screen-question').value,image:canvas.toDataURL('image/jpeg',.7)});result(r.reply);audit('screen.analyze','One approved frame sent to '+data.brain);});};}
if(id==='files'){content.innerHTML='<p class="muted">Search only files you explicitly select. File content stays on this device. Remote website actions need an owner-configured browser runner and your review. Do not paste passwords, cookies or recovery codes.</p><label class="button">Choose a folder<input id="folder-input" type="file" webkitdirectory multiple hidden></label><label class="button">Choose files<input id="files-input" type="file" multiple hidden></label><label class="search-label">File name search<input id="file-search" placeholder="Filter selected files…"></label><div id="file-results" class="tool-result"></div><h3>Website account runner</h3>'+formHTML(field('browser-url','Public HTTPS target URL','url')+field('browser-account','Opaque connected account ID','text','',false)+field('browser-action','Requested action','text','Read the page title and summarize the content')+'<div class="local-actions"><button type="submit" class="primary">REVIEW & RUN ACTION</button><button id="browser-connect" type="button">Open secure account connection</button></div>');let selected=[];const render=()=>{const q=$('file-search').value.toLowerCase(),r=$('file-results');r.replaceChildren();for(const f of selected.filter(f=>(f.webkitRelativePath||f.name).toLowerCase().includes(q)).slice(0,100)){const b=node('button',`${f.webkitRelativePath||f.name} · ${Math.round(f.size/1024)} KB`);b.onclick=async()=>{if(f.size>1000000)return toast('Preview limited to text files under 1 MB.');if(!/\.(txt|md|json|csv|js|css|html|log)$/i.test(f.name))return toast('Text preview only.');const p=node('pre',(await f.text()).slice(0,20000));r.append(p);};r.append(b);}};$('folder-input').onchange=e=>{selected=[...e.target.files];render();audit('files.select',`${selected.length} user-selected files; not uploaded.`);};$('files-input').onchange=$('folder-input').onchange;$('file-search').oninput=render;$('browser-connect').onclick=()=>guard(async()=>{const r=await api('/api/browser/connect',{url:$('browser-url').value});const a=safeLink(r.url,'Connect securely on the browser provider');$('tool-result').replaceChildren(a);});$('active-tool-form').onsubmit=e=>{e.preventDefault();guard(async()=>{if(!status.browserConfigured)throw Error('Remote browser runner is not configured. Set BROWSER_AGENT_URL, BROWSER_AGENT_KEY, BROWSER_ALLOWED_HOSTS and APP_ACCESS_TOKEN.');const body={url:$('browser-url').value,accountId:$('browser-account').value,action:$('browser-action').value};if(!await approve('Authorize website action?',`${body.url}\nAccount ID: ${body.accountId||'Anonymous'}\n${body.action}\nRunner must pause before purchases, messages or destructive changes.`))return;const r=await api('/api/browser/run',{...body,approved:true,requestId:crypto.randomUUID()});result(JSON.stringify(r,null,2));audit('browser.run',r.status||'Runner response received; inspect transcript.');});};}
if(id==='business'){content.innerHTML='<p class="muted">DISCOVER → VERIFY → BUILD → DRAFT → APPROVE. Live search requires Tavily. A missing website in a search result is not proof a business has none. Verify rating, website ownership and the published contact before outreach. No fake leads, claims or preview links.</p>'+formHTML(field('business-query','Discovery mission','text','Find 5-star restaurants in Miami without a website')+'<button type="submit" class="primary">1 / DISCOVER LIVE LEADS</button>')+'<div id="lead-results" class="tool-result"></div><h3>2 / Verified business brief</h3><form class="tool-form" id="business-build">'+field('business-name','Verified restaurant name')+field('business-source','Published source URL','url')+field('business-rating','Observed rating / evidence')+field('business-email','Published contact email','email')+field('business-description','Brand / cuisine / location brief')+'<label>Verified menu items (one per line; leave blank if unknown)<textarea id="business-menu"></textarea></label><label>Photo URLs you have rights to use (one HTTPS URL per line; optional)<textarea id="business-photos"></textarea></label><label><input id="business-verified" type="checkbox" required> I verified the contact and rating; this is a speculative website draft, not a claim of ownership.</label><button type="submit" class="primary">3 / BUILD WEBSITE + $500 PITCH</button></form><div id="business-preview"></div><div id="business-outreach"></div>';let activeMission;$('active-tool-form').onsubmit=e=>{e.preventDefault();guard(async()=>{activeMission=mission($('business-query').value,['Search live sources','User verifies lead','Generate website draft','Review outreach']);const r=await api('/api/research',{query:$('business-query').value});step(activeMission,0,'Live search returned cited results');const target=$('lead-results');target.replaceChildren(node('p',r.answer||'Review the cited sources. No business has been marked qualified automatically.'));for(const s of r.results){target.append(safeLink(s.url,s.title),node('p',s.content));}audit('business.discovery',`${r.results.length} cited search results; qualification pending.`);});};$('business-build').onsubmit=e=>{e.preventDefault();const name=$('business-name').value,email=$('business-email').value,brief=$('business-description').value,source=$('business-source').value,rating=$('business-rating').value;try{const u=new URL(source);if(!['https:','http:'].includes(u.protocol))throw Error();}catch{return toast('Supply a valid published source URL.');}const menu=$('business-menu').value.split('\n').filter(Boolean);const photos=$('business-photos').value.split('\n').filter(Boolean).filter(s=>{try{return new URL(s).protocol==='https:';}catch{return false;}}).slice(0,3);const html=restaurantHTML(name,brief,menu,photos);if(!activeMission)activeMission=mission('Website for '+name,['Record verified lead','Generate website','Prepare pitch']);step(activeMission,1,`User verified: ${name}; ${rating}; ${source}`);preview($('business-preview'),html,'restaurant-website-draft.html');step(activeMission,2,'Standalone responsive HTML draft generated');const outreach=$('business-outreach');outreach.innerHTML='<h3>4 / Review the outreach</h3><p class="muted">Host the downloadable website on your own service first, then enter its real preview URL. Jarvis does not invent a live link. Cold outreach must follow applicable email rules and your sender identity must be accurate.</p><form id="business-pitch" class="tool-form">'+field('pitch-link','Actual hosted preview URL','url')+field('pitch-sender','Your name / business identity')+field('pitch-address','Business mailing address (for commercial email)')+'<button type="submit" class="primary">GENERATE PITCH DRAFT</button></form><div id="pitch-result" class="tool-result"></div>';$('business-pitch').onsubmit=ev=>{ev.preventDefault();const link=$('pitch-link').value,identity=$('pitch-sender').value,address=$('pitch-address').value;let u;try{u=new URL(link);if(u.protocol!=='https:')throw Error();}catch{return toast('Use a real hosted HTTPS preview link.');}const body=`Hello ${name} team,\n\nI am ${identity}. I put together an independent, speculative website concept for ${name}. You can preview it here: ${u.href}\n\nIf you like the direction, I would be happy to discuss selling this website draft for $500. Hosting, revisions and transfer terms would be agreed before any payment. This is a concept, not your official website.\n\nIf you are not interested, reply and I will not contact you again.\n\n${identity}\n${address}`;const draft={id:crypto.randomUUID(),to:email,subject:`A website concept for ${name} — $500`,body,at:new Date().toISOString()};data.drafts.unshift(draft);remember('contact',name,`Email: ${email}\nRating evidence: ${rating}\nSource: ${source}\n${brief}`);persist();const r=$('pitch-result');r.replaceChildren(node('pre',`To: ${email}\nSubject: ${draft.subject}\n\n${body}`));const edit=node('button','Open in email studio');edit.onclick=async()=>{await openTool('email');$('email-to').value=draft.to;$('email-subject').value=draft.subject;$('email-body').value=draft.body;};r.append(edit);finish(activeMission,'Website and outreach draft created. Nothing sent.','AWAITING SEND APPROVAL');audit('business.draft','Verified contact + website draft + $500 pitch. Not sent.');};};}
if(id==='registry'){content.innerHTML='<p class="muted">Tools use a shared permission-aware API layer. Missing capabilities become structured tool requests, not untrusted executable code. Developer-installed adapters can extend the registry.</p><div id="registry-list"></div><h3>Request a new capability</h3>'+formHTML(field('new-tool-name','Capability name')+field('new-tool-description','What should it do?')+'<button type="submit" class="primary">REGISTER TOOL REQUEST</button>')+'<h3>Owner access</h3><p class="muted">If the server is owner-gated, enter APP_ACCESS_TOKEN here. It is kept only in this tab session, never in memory exports. Configure actual provider keys only in Render.</p><label>Owner access token<input id="owner-access" type="password" autocomplete="off"></label><div class="local-actions"><button id="owner-save">Use for this session</button><button id="owner-clear">Forget token</button><button id="cloud-save">Sync memory backup</button><button id="cloud-load">Restore cloud backup</button><button id="google-disconnect">Disconnect Google</button></div><h3>Provider status</h3><pre id="provider-status"></pre>';const list=$('registry-list');for(const t of [...registry,...data.tools]){const a=node('article',undefined,'record');a.append(node('strong',t.name),node('small',' / '+t.mode),node('p',t.description));list.append(a);}$('provider-status').textContent=JSON.stringify({brains:status.brains,search:status.searchConfigured,email:status.emailConfigured,browser:status.browserConfigured,memory:status.memory},null,2);$('active-tool-form').onsubmit=e=>{e.preventDefault();const t={id:crypto.randomUUID(),name:$('new-tool-name').value,description:$('new-tool-description').value,mode:'REQUESTED — implementation required'};data.tools.push(t);remember('project','Tool request: '+t.name,t.description);audit('tool.register','Capability request saved; not executable.');result('Tool request registered. A developer must implement and review the adapter before execution.');};$('owner-save').onclick=()=>{sessionStorage.setItem('jarvis.access',$('owner-access').value);$('owner-access').value='';toast('Owner token retained only in this tab session.');refreshStatus();};$('owner-clear').onclick=()=>{sessionStorage.removeItem('jarvis.access');toast('Owner token forgotten.');};$('cloud-save').onclick=()=>guard(async()=>{if(!await approve('Sync memory to the configured store?','Structured records, projects and mission history will be sent to the server-backed memory provider. No passwords are included.'))return;const r=await api('/api/memory',{operation:'save',vault:vaultId(),data});result(r.message);audit('memory.sync',r.message);});$('cloud-load').onclick=()=>guard(async()=>{const r=await api('/api/memory',{operation:'load',vault:vaultId()});if(!r.data)return result('No cloud backup for this device.');if(await approve('Restore cloud memory?','This merges records and history from your device vault.')){mergeData(r.data);result('Cloud backup merged.');}});$('google-disconnect').onclick=()=>guard(async()=>{await api('/api/disconnect',{});await refreshStatus();result('Google disconnected.');});}}
function vaultId(){let id=localStorage.getItem('jarvis.vault');if(!id){id=crypto.randomUUID();localStorage.setItem('jarvis.vault',id);}return id;}
function stopScreen(){screenStream?.getTracks().forEach(t=>t.stop());screenStream=null;if(screenVideo)screenVideo.srcObject=null;$('observation-state').textContent='OFFLINE';audit('screen.stop','Screen sharing stopped.');}
function preview(target,html,filename){target.replaceChildren();const iframe=node('iframe',undefined,'preview-frame');iframe.title='Sandboxed generated document preview';iframe.setAttribute('sandbox','');iframe.srcdoc=html;const save=node('button','Download HTML');save.onclick=()=>download(filename,html,'text/html');const note=node('p','Sandboxed draft. Download, review, then open the HTML to print/save as PDF.','muted');target.append(iframe,save,note);}
function documentHTML(title,body){return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(title)}</title><style>body{font:15px system-ui;background:#fff;color:#152436;max-width:850px;margin:50px auto;padding:35px}h1{font-size:40px;letter-spacing:-.04em}h2{font-size:23px}p,li{line-height:1.9}table{width:100%;border-collapse:collapse;margin:35px 0}td,th{text-align:left;border-bottom:1px solid #dae0e8;padding:15px 10px}.label{color:#78909d;letter-spacing:.2em;font-size:10px}@media print{body{margin:0;padding:20px}}</style></head><body>${body}</body></html>`;}
function restaurantHTML(name,brief,menu,photos){const image=photos[0]?`<img src="${escapeHTML(photos[0])}" alt="Restaurant concept photography">`:'<div class="art"><span>✦</span></div>';return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(name)} / Website Concept</title><style>*{box-sizing:border-box}body{margin:0;background:#141915;color:#f1ead9;font:16px Georgia,serif}nav{display:flex;justify-content:space-between;padding:28px 6vw;border-bottom:1px solid #394135;font:11px system-ui;letter-spacing:.15em}a{color:#d0ae6f;text-decoration:none}main{max-width:1400px;margin:auto}.hero{display:grid;grid-template-columns:1fr 1fr;min-height:600px;align-items:center}.copy{padding:60px 6vw}small{font:10px system-ui;letter-spacing:.23em;color:#caa66b}h1{font-size:clamp(42px,6vw,86px);font-weight:400;line-height:1.06;letter-spacing:-.04em}p{color:#bdc4b6;line-height:1.9}img{width:100%;height:600px;object-fit:cover}.art{height:600px;display:grid;place-items:center;background:radial-gradient(ellipse at 55% 35%,#a46b3144,transparent 45%),linear-gradient(135deg,#1e392d,#142019);border-left:1px solid #394135}.art span{font-size:170px;color:#bd995b;text-shadow:0 0 80px #bd995b66}.cta{display:inline-block;padding:16px 26px;border:1px solid #bf9f65;margin-top:20px;font:10px system-ui;letter-spacing:.1em}.section{padding:70px 6vw;border-top:1px solid #394135}h2{font-size:38px;font-weight:400}.menu{display:grid;grid-template-columns:1fr 1fr;gap:20px}.dish{padding:20px 0;border-bottom:1px solid #394135}footer{padding:30px 6vw;color:#929b8c;font:10px system-ui;line-height:1.7;border-top:1px solid #394135}@media(max-width:700px){.hero{grid-template-columns:1fr}img,.art{height:320px}.copy{padding:50px 7vw}.menu{grid-template-columns:1fr}}</style></head><body><nav><strong>${escapeHTML(name.toUpperCase())}</strong><a href="#menu">MENU & EXPERIENCE</a></nav><main><section class="hero"><div class="copy"><small>AN INDEPENDENT WEBSITE CONCEPT</small><h1>${escapeHTML(name)}</h1><p>${escapeHTML(brief)}</p><a class="cta" href="#menu">EXPLORE THE CONCEPT ↗</a></div>${image}</section><section class="section" id="menu"><small>THE TABLE</small><h2>A taste of what awaits.</h2><div class="menu">${menu.length?menu.map(m=>`<div class="dish">${escapeHTML(m)}</div>`).join(''):'<p>Menu content awaits owner approval. No unverified dishes or prices are displayed.</p>'}</div></section><section class="section"><small>YOUR NEXT CHAPTER</small><h2>Make an impression.</h2><p>This design is a starting point. Photography, booking details, opening hours and business information must be supplied or approved by the owner before launch.</p></section></main><footer>Independent speculative design concept / Not an official restaurant website.<br>Contact and reservations are intentionally disabled until owner approval. Photos, if supplied, must be licensed.</footer></body></html>`;}
function mergeData(incoming){for(const key of ['records','missions','audit','drafts','events','tools'])if(Array.isArray(incoming[key])){const valid=incoming[key].filter(x=>x&&typeof x==='object'&&typeof x.id==='string');data[key]=[...new Map([...data[key],...valid].map(x=>[x.id,x])).values()];}persist();renderMemory();renderMissions();renderAudit();}
$('command-form').onsubmit=e=>{e.preventDefault();submit($('command').value);};$('mic').onclick=toggleMic;$('reactor').onclick=()=>{if(window.speechSynthesis?.speaking){interrupt();startListening();}else toggleMic();};$('ear').onclick=()=>{handsfree=!handsfree;stopped=false;updateEar();if(handsfree)startListening();else recognition?.stop();};$('speak').onchange=()=>{if(!$('speak').checked)interrupt();};$('voice').onchange=()=>{data.voice=$('voice').value;persist();};$('interrupt').onclick=interrupt;
$('stop').onclick=()=>{stopped=true;handsfree=false;generation++;activeController?.abort();recognition?.abort();interrupt();clearTimeout(callTimer);callTimer=null;busy=false;for(const m of data.missions)if(m.state==='RUNNING')finish(m,'Stopped by user.','CANCELLED');if(screenStream)stopScreen();updateEar();setState('stopped');api('/api/stop',{}).catch(()=>{});audit('emergency.stop','Local microphone, speech, capture and missions stopped; completed actions cannot be undone.');};
$('close-tool').onclick=()=>{$('tool-dialog').close();clearTimeout(callTimer);callTimer=null;uiGeneration++;};$('tool-dialog').addEventListener('cancel',()=>{clearTimeout(callTimer);callTimer=null;uiGeneration++;});document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>submit(b.dataset.command));
$('record-form').onsubmit=e=>{e.preventDefault();remember($('record-type').value,$('record-title').value,$('record-detail').value);$('record-form').reset();audit('memory.write','User-authored structured record saved on this device.');};$('memory-search').oninput=renderMemory;$('export-memory').onclick=()=>download('jarvis-memory-backup.json',JSON.stringify({schema:1,exportedAt:new Date().toISOString(),...data},null,2));$('import-memory').onchange=e=>guard(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Import limited to 5 MB.');const text=await f.text();if(f.name.endsWith('.json')){let imported;try{imported=JSON.parse(text);}catch{throw Error('Invalid JSON file.');}if(Array.isArray(imported.records))mergeData(imported);else remember('project','Imported AI context: '+f.name,text);}else remember('project','Imported AI context: '+f.name,text);audit('memory.import',f.name+'; inspect imported context before use.');toast('Context imported into device memory.');e.target.value='';});$('clear-memory').onclick=async()=>{if(await approve('Clear local memory?','This deletes structured memory, drafts, local events and mission history on this device. Export a backup first. Cloud backups are not deleted.')){data={...defaults,records:[],missions:[],audit:[],drafts:[],events:[],tools:[]};persist();renderMemory();renderMissions();renderAudit();toast('Local memory cleared.');}};
function tick(){$('clock').textContent=new Date().toLocaleTimeString(undefined,{hour12:false});}$('timezone').textContent=Intl.DateTimeFormat().resolvedOptions().timeZone;tick();setInterval(tick,1000);for(let i=0;i<36;i++)$('waveform').append(node('i'));document.body.dataset.brain=data.brain;$('brain-label').textContent=brains.find(b=>b.id===data.brain).name.toUpperCase();renderMemory();renderMissions();renderAudit();renderCounts();updateEar();setState('idle');refreshStatus();message('assistant','Online, sir. Speak a mission, switch my brain, or open a tool. I remember on this device and use only configured providers. Real actions require evidence and your permission.');
